$source = "C:\Users\renu5\Downloads\Takeout\Google Photos"
$dest = "G:\My Drive\Google Photos"

Write-Host "Scanning destination..."
$destFiles = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
Get-ChildItem -Path $dest -File -Recurse | ForEach-Object {
    $relPath = $_.FullName.Substring($dest.Length).TrimStart('\')
    [void]$destFiles.Add($relPath)
}

Write-Host "Scanning source and comparing..."
$missingFiles = [System.Collections.Generic.List[string]]::new()
$overlapCount = 0

Get-ChildItem -Path $source -File -Recurse | ForEach-Object {
    $relPath = $_.FullName.Substring($source.Length).TrimStart('\')
    if ($destFiles.Contains($relPath)) {
        $overlapCount++
    } else {
        $missingFiles.Add($_.FullName)
    }
}

$missingCount = $missingFiles.Count
$missingFiles | Out-File "C:\Users\renu5\Downloads\Takeout\missing_files_list.txt" -Encoding utf8

Write-Output "Overlap: $overlapCount"
Write-Output "Missing: $missingCount"
Write-Output "List saved to: C:\Users\renu5\Downloads\Takeout\missing_files_list.txt"

$sourceBase = "C:\Users\renu5\Downloads\Takeout\Google Photos"
$destBase = "C:\Users\renu5\Downloads\Takeout\Google Photos Missing"

if (!(Test-Path $destBase)) { New-Item -ItemType Directory -Force -Path $destBase | Out-Null }

$missingFiles = Get-Content "C:\Users\renu5\Downloads\Takeout\missing_files_list.txt" -Encoding utf8
$count = 0
foreach ($file in $missingFiles) {
    if (Test-Path $file) {
        $relPath = $file.Substring($sourceBase.Length).TrimStart('\')
        $destPath = Join-Path $destBase $relPath
        $destDir = Split-Path $destPath
        if (!(Test-Path $destDir)) { New-Item -ItemType Directory -Force -Path $destDir | Out-Null }
        Copy-Item -Path $file -Destination $destPath
        $count++
    }
}
Write-Output "Copied $count missing files to $destBase"

$source = "C:\Users\renu5\Downloads\Takeout\Google Photos"
$dest1 = "G:\My Drive\Google Photos"
$dest2 = "G:\My Drive\Google Photos Missing"

Write-Host "Scanning Google Drive folders..."
$uploadedFiles = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)

if (Test-Path $dest1) {
    Get-ChildItem -Path $dest1 -File -Recurse | ForEach-Object {
        $relPath = $_.FullName.Substring($dest1.Length).TrimStart('\')
        [void]$uploadedFiles.Add($relPath)
    }
}

if (Test-Path $dest2) {
    Get-ChildItem -Path $dest2 -File -Recurse | ForEach-Object {
        $relPath = $_.FullName.Substring($dest2.Length).TrimStart('\')
        [void]$uploadedFiles.Add($relPath)
    }
}

Write-Host "Total unique uploaded files found in Drive: $($uploadedFiles.Count)"
Write-Host "Comparing with local Takeout folder..."

$finalMissing = [System.Collections.Generic.List[string]]::new()
$sourceCount = 0

Get-ChildItem -Path $source -File -Recurse | ForEach-Object {
    $sourceCount++
    $relPath = $_.FullName.Substring($source.Length).TrimStart('\')
    if (-not $uploadedFiles.Contains($relPath)) {
        $finalMissing.Add($_.FullName)
    }
}

$missingCount = $finalMissing.Count
Write-Host "Total files in local Takeout: $sourceCount"

if ($missingCount -gt 0) {
    $finalMissing | Out-File "C:\Users\renu5\Downloads\Takeout\final_missing.txt" -Encoding utf8
    Write-Output "RESULT: WARNING - Found $missingCount files still missing!"
    Write-Output "List saved to C:\Users\renu5\Downloads\Takeout\final_missing.txt"
} else {
    Write-Output "RESULT: SUCCESS - All $sourceCount files are accounted for! 0 files missing."
}
